B: ROT N
まず元の文字がアルファベットの何番目の文字かを0-indexed で求め、それにN を加えて26 で
割った余りを求めると、出力するべき文字が分かります。
1 #include<stdio.h>
2 #include<string.h>
3 int main(){
4
int n;
5
char s[10010];
6
scanf("%d␣%s",&n,s);
7
int len=strlen(s);
8
for(int i=0;i<len;i++){
9
int x=s[i]-'A';
10
x=(x+n)%26;
11
putchar('A'+x);
12
}
13
putchar('\n');
14 }
